import argparseimport jsonfrom pathlib import Pathimport cv2import numpy as npdef clamp_bbox(x1, y1, x2, y2, width, height, padding=0):    x1 = max(0, min(x1 - padding, width - 1))    y1 = max(0, min(y1 - padding, height - 1))    x2 = max(0, min(x2 + padding, width - 1))    y2 = max(0, min(y2 + padding, height - 1))    return x1, y1, x2, y2def remove_object(frame, bbox, mode="blur", padding=10):    height, width = frame.shape[:2]    x1 = bbox["x1"]    y1 = bbox["y1"]    x2 = bbox["x2"]    y2 = bbox["y2"]    x1, y1, x2, y2 = clamp_bbox(        x1,        y1,        x2,        y2,        width,        height,        padding=padding,    )    if x2 <= x1 or y2 <= y1:        return frame    if mode == "black":        frame[y1:y2, x1:x2] = (0, 0, 0)    elif mode == "blur":        roi = frame[y1:y2, x1:x2]        if roi.size > 0:            blurred = cv2.GaussianBlur(roi, (51, 51), 0)            frame[y1:y2, x1:x2] = blurred    elif mode == "inpaint":        mask = np.zeros(frame.shape[:2], dtype=np.uint8)        mask[y1:y2, x1:x2] = 255        frame = cv2.inpaint(frame, mask, 3, cv2.INPAINT_TELEA)    else:        raise ValueError(f"Неизвестный режим удаления: {mode}")    return framedef remove_objects_from_video(    input_video,    input_json,    output_video,    mode="inpaint",    padding=10,    classes=None,    min_conf=0.0,):    with open(input_json, "r", encoding="utf-8") as f:        annotations = json.load(f)    frames_data = annotations["frames"]    # Для быстрого доступа: frame_index -> objects    frame_objects = {        frame_data["frame_index"]: frame_data["objects"]        for frame_data in frames_data    }    cap = cv2.VideoCapture(input_video)    if not cap.isOpened():        raise RuntimeError(f"Не удалось открыть видео: {input_video}")    fps = cap.get(cv2.CAP_PROP_FPS)    width = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH))    height = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT))    Path(output_video).parent.mkdir(parents=True, exist_ok=True)    fourcc = cv2.VideoWriter_fourcc(*"mp4v")    writer = cv2.VideoWriter(output_video, fourcc, fps, (width, height))    frame_index = 0    while True:        ret, frame = cap.read()        if not ret:            break        objects = frame_objects.get(frame_index, [])        for obj in objects:            class_id = int(obj["class_id"])            confidence = float(obj["confidence"])            if classes is not None and class_id not in classes:                continue            if confidence < min_conf:                continue            frame = remove_object(                frame,                obj["bbox"],                mode=mode,                padding=padding,            )        writer.write(frame)        frame_index += 1        if frame_index % 30 == 0:            print(f"Обработано кадров: {frame_index}")    cap.release()    writer.release()    print(f"Готово. Видео сохранено: {output_video}")def parse_classes(classes_str):    if classes_str is None:        return None    return [int(x.strip()) for x in classes_str.split(",") if x.strip()]def main():    parser = argparse.ArgumentParser()    parser.add_argument(        "--input",        required=True,        help="Путь к исходному видео",    )    parser.add_argument(        "--json",        required=True,        help="Путь к JSON-разметке",    )    parser.add_argument(        "--output",        default="output/removed_video.mp4",        help="Куда сохранить видео после удаления объектов",    )    parser.add_argument(        "--mode",        choices=["blur", "black", "inpaint"],        default="inpaint",        help="Способ удаления: blur, black или inpaint",    )    parser.add_argument(        "--padding",        type=int,        default=10,        help="Насколько расширять рамку объекта при удалении",    )    parser.add_argument(        "--classes",        default=None,        help="ID классов через запятую, например 0,1,2. Если не указано, удаляются все.",    )    parser.add_argument(        "--min-conf",        type=float,        default=0.0,        help="Минимальная confidence для удаления объекта из JSON",    )    args = parser.parse_args()    remove_objects_from_video(        input_video=args.input,        input_json=args.json,        output_video=args.output,        mode=args.mode,        padding=args.padding,        classes=parse_classes(args.classes),        min_conf=args.min_conf,    )if __name__ == "__main__":    main()